package cn.iocoder.yudao.module.zsjos.dal.mysql.studentops; import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.studentops.ExceptionTicketDO; import org.apache.ibatis.annotations.Mapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import java.util.List; @Mapper public interface ExceptionTicketMapper extends BaseMapperX<ExceptionTicketDO>{default List<ExceptionTicketDO> selectByOwner(Long uid){return selectList(new LambdaQueryWrapper<ExceptionTicketDO>().eq(ExceptionTicketDO::getOwnerUserId,uid).orderByDesc(ExceptionTicketDO::getUpdateTime).orderByDesc(ExceptionTicketDO::getId));}default int resolve(Long id,Integer version,String resolution){return update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<ExceptionTicketDO>().eq(ExceptionTicketDO::getId,id).eq(ExceptionTicketDO::getVersion,version).eq(ExceptionTicketDO::getStatus,"open").set(ExceptionTicketDO::getStatus,"resolved").set(ExceptionTicketDO::getResolution,resolution).set(ExceptionTicketDO::getResolvedAt,java.time.LocalDateTime.now()).set(ExceptionTicketDO::getVersion,version+1));}}
